<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersion;

final class ThemeVersionUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = ThemeVersion::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTheme(), $other->getTheme());
        $this->assertTrue($one->isThemeChanged());
        $this->assertEquals($one->getChannel(), $other->getChannel());
        $this->assertTrue($one->isChannelChanged());
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );
        $other = new ThemeVersion(
            uid: 'other',
            theme: new ThemeRef('other'),
            channel: ThemeVersionChannelOptions::HTML,
            locale: 'other',
            contentHtml: 'other',
            contentText: 'other',
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTheme(), $other->getTheme());
        $this->assertTrue($one->isThemeChanged($base));
        $this->assertEquals($one->getChannel(), $other->getChannel());
        $this->assertTrue($one->isChannelChanged($base));
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged($base));
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged($base));
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['theme']['$ref']);
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $json['channel']);
        $this->assertEquals('one', $json['locale']);
        $this->assertEquals(1, $json['version']);
    }
    public function test_create_store_values(): void
    {
        // @Arrange
        $one = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = ThemeVersion::create($one->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTheme(), $other->getTheme());
        $this->assertTrue($one->isThemeChanged());
        $this->assertEquals($one->getChannel(), $other->getChannel());
        $this->assertTrue($one->isChannelChanged());
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
        $this->assertCount(0, $one->getTheEvents());
        $this->assertCount(1, $other->getTheEvents());
    }
    public function test_update_change_values(): void
    {
        $base = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );
        $other = new ThemeVersion(
            uid: 'other',
            theme: new ThemeRef('other'),
            channel: ThemeVersionChannelOptions::HTML,
            locale: 'other',
            contentHtml: 'other',
            contentText: 'other',
            version: 2,
        );

        // @Act
        $one = $base->update($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTheme(), $other->getTheme());
        $this->assertTrue($one->isThemeChanged($base));
        $this->assertEquals($one->getChannel(), $other->getChannel());
        $this->assertTrue($one->isChannelChanged($base));
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged($base));
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged($base));
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
        $this->assertCount(0, $other->getTheEvents());
        $this->assertCount(1, $one->getTheEvents());
    }
    public function test_delete_store_values(): void
    {
        // @Arrange
        $one = new ThemeVersion(
            uid: 'one',
            theme: new ThemeRef('one'),
            channel: ThemeVersionChannelOptions::MAIL,
            locale: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = $one->delete();

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTheme(), $other->getTheme());
        $this->assertTrue($one->isThemeChanged());
        $this->assertEquals($one->getChannel(), $other->getChannel());
        $this->assertTrue($one->isChannelChanged());
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
}
